import * as THREE from 'https://esm.sh/three@0.166.1';

const mount = document.querySelector('#game');
const scene = new THREE.Scene();
scene.background = new THREE.Color('#a9a393');
scene.fog = new THREE.FogExp2('#a9a393', 0.0085);
const camera = new THREE.PerspectiveCamera(72, innerWidth / innerHeight, .1, 420);
const renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance' });
renderer.setSize(innerWidth, innerHeight); renderer.setPixelRatio(Math.min(devicePixelRatio, 1.7));
renderer.shadowMap.enabled = true; renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace; renderer.toneMapping = THREE.ACESFilmicToneMapping; renderer.toneMappingExposure = 1.15;
mount.appendChild(renderer.domElement);
scene.add(new THREE.HemisphereLight(0xc3c8c0, 0x40362b, 1.7));
const sun = new THREE.DirectionalLight(0xffddb0, 3.1); sun.position.set(-38, 65, 34); sun.castShadow = true;
sun.shadow.mapSize.set(1024,1024); sun.shadow.camera.left=-80;sun.shadow.camera.right=80;sun.shadow.camera.top=80;sun.shadow.camera.bottom=-80; sun.shadow.bias=-.0003;scene.add(sun);
const ambient = new THREE.AmbientLight(0x9ca5a2,.35);scene.add(ambient);

const mat=(color,rough=.9,extra={})=>new THREE.MeshStandardMaterial({color,roughness:rough,...extra});
const mats={ground:mat('#655c4d'),rock:mat('#514d46'),rockLight:mat('#777062'),bark:mat('#463c32'),barkLight:mat('#655245'),mushroom:mat('#aa5943'),mushroom2:mat('#c67d58'),cloth:mat('#80604b'),clothLight:mat('#c4a878'),skin:mat('#ad795d'),dark:mat('#252727'),metal:mat('#85877c',.48,{metalness:.65}),leaf:mat('#6a6655'),leaf2:mat('#8b7557')};
const terrainHeight=(x,z)=>{
 const d=Math.hypot(x,z); const base=-1.6+Math.sin(x*.057+1.3)*1.05+Math.cos(z*.067)*.8+Math.sin((x+z)*.12)*.42+Math.sin(x*.22)*Math.cos(z*.18)*.24;
 const ridge=Math.max(0,1-Math.hypot(x-4,z+37)/38); const hills=Math.max(0,1-Math.hypot(x+35,z-12)/32)*4+Math.max(0,1-Math.hypot(x-38,z-24)/28)*3;
 return base+ridge*ridge*15+hills+(d>72?-Math.pow((d-72)/16,2)*5:0);
};
function makeTerrain(){
 const n=180,size=210, geo=new THREE.PlaneGeometry(size,size,n,n); geo.rotateX(-Math.PI/2);
 const p=geo.attributes.position, colors=[]; const c1=new THREE.Color('#675b4b'), c2=new THREE.Color('#877457'), c3=new THREE.Color('#4e5149'), c4=new THREE.Color('#b08b65');
 for(let i=0;i<p.count;i++){const x=p.getX(i),z=p.getZ(i),h=terrainHeight(x,z);p.setY(i,h);const grain=(Math.sin(x*3.1+z*2.7)*.025);let c=c1.clone().lerp(c2,THREE.MathUtils.clamp((h+2)/12,0,.7));const moss=(Math.sin(x*.19)*Math.cos(z*.14)+1)*.12;c.lerp(c3,moss);if(h>9)c.lerp(c4,THREE.MathUtils.clamp((h-9)/12,0,.5));c.offsetHSL(0,0,grain);colors.push(c.r,c.g,c.b)}
 geo.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));geo.computeVertexNormals();const mesh=new THREE.Mesh(geo,new THREE.MeshStandardMaterial({vertexColors:true,roughness:1}));mesh.receiveShadow=true;scene.add(mesh);
 const water=new THREE.Mesh(new THREE.PlaneGeometry(440,440),new THREE.MeshStandardMaterial({color:'#394d50',roughness:.36,metalness:.12,transparent:true,opacity:.91}));water.rotation.x=-Math.PI/2;water.position.y=-2.5;scene.add(water);
}
makeTerrain();
function mesh(geometry,material,parent=scene){const m=new THREE.Mesh(geometry,material);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function rock(x,z,s=1){const m=mesh(new THREE.DodecahedronGeometry(s,0),Math.random()<.5?mats.rock:mats.rockLight);m.position.set(x,terrainHeight(x,z)+s*.35,z);m.scale.set(1+Math.random()*.6,.55+Math.random()*.8,.8+Math.random()*.5);m.rotation.set(Math.random(),Math.random()*3,Math.random());return m}
function mushroom(x,z,s=1){const group=new THREE.Group();group.position.set(x,terrainHeight(x,z),z);scene.add(group);const stem=mesh(new THREE.CylinderGeometry(.13*s,.23*s,1.3*s,7),mats.mushroom2,group);stem.position.y=.65*s;const cap=mesh(new THREE.SphereGeometry(.92*s,9,6,0,Math.PI*2,0,Math.PI*.53),Math.random()<.5?mats.mushroom:mats.mushroom2,group);cap.position.y=1.28*s;cap.scale.y=.48;const spots=mesh(new THREE.SphereGeometry(.1*s,6,5),mat('#e3bb84'),group);spots.position.set(.35*s,1.59*s,.4*s);return group}
function tree(x,z,s=1){const g=new THREE.Group();g.position.set(x,terrainHeight(x,z),z);scene.add(g);let trunk=mesh(new THREE.CylinderGeometry(.16*s,.32*s,2.4*s,7),mats.bark,g);trunk.position.y=1.2*s;trunk.rotation.z=.12;for(let i=0;i<4;i++){const b=mesh(new THREE.IcosahedronGeometry((.7+Math.random()*.35)*s,0),i%2?mats.leaf:mats.leaf2,g);b.position.set((Math.random()-.5)*.8*s,(2.3+i*.55)*s,(Math.random()-.5)*.8*s);b.scale.set(1.1,.7,1); }return g}
function buildLandmarks(){
 // The distant Red Mountain silhouette, layered in volcanic shelves.
 for(let i=0;i<5;i++){const r=25-i*4, h=17+i*7;const cone=mesh(new THREE.ConeGeometry(r,h,9,3),i%2?mat('#5a4d47'):mat('#6b5648'));cone.position.set(4,4+h/2,-48);cone.rotation.y=.18*i;cone.castShadow=false;}
 // Broken basalt pillars and outcrops.
 for(let i=0;i<40;i++){let a=Math.random()*Math.PI*2,d=18+Math.random()*65,x=Math.cos(a)*d,z=Math.sin(a)*d; if(Math.hypot(x,z)<13)continue;rock(x,z,.5+Math.random()*2.2)}
 for(let i=0;i<44;i++){let a=Math.random()*Math.PI*2,d=12+Math.random()*57,x=Math.cos(a)*d,z=Math.sin(a)*d;if((x>8&&x<34&&z>15&&z<40)||Math.hypot(x,z)<10)continue; if(Math.random()<.64)mushroom(x,z,.7+Math.random()*2);else tree(x,z,.65+Math.random()*1.25)}
 // Ancient ash columns
 for(const [x,z,h] of [[-25,20,7],[31,8,10],[44,-22,8],[-44,-28,6],[18,56,11]]){const col=mesh(new THREE.CylinderGeometry(.65,1.05,h,7),mat('#706253'));col.position.set(x,terrainHeight(x,z)+h/2,z);const cap=mesh(new THREE.CylinderGeometry(1.5,1.25,.55,7),mat('#87745c'));cap.position.set(x,terrainHeight(x,z)+h,z);}
 // A small ruined shrine frames the guide's camp.
 const sx=-7,sz=13,sy=terrainHeight(sx,sz);for(const dx of [-3.1,3.1]){const p=mesh(new THREE.BoxGeometry(.8,5,.9),mat('#776650'));p.position.set(sx+dx,sy+2.5,sz-2)}const lintel=mesh(new THREE.BoxGeometry(7,.85,1.1),mat('#897354'));lintel.position.set(sx,sy+5,sz-2);const brazier=mesh(new THREE.CylinderGeometry(.5,.7,.35,8),mats.metal);brazier.position.set(sx,sy+.3,sz+1);const fire=mesh(new THREE.SphereGeometry(.35,8,7),new THREE.MeshBasicMaterial({color:'#e9954f'}));fire.position.set(sx,sy+.8,sz+1);
}
buildLandmarks();
const beaconMat=new THREE.MeshBasicMaterial({color:'#efbd74',transparent:true,opacity:.38,side:THREE.DoubleSide,depthWrite:false});
function createShard(x,z,i){const y=terrainHeight(x,z);const g=new THREE.Group();g.position.set(x,y+.9,z);scene.add(g);const crystal=mesh(new THREE.OctahedronGeometry(.58,0),new THREE.MeshStandardMaterial({color:'#f0b968',emissive:'#ca6c25',emissiveIntensity:1.6,metalness:.18,roughness:.24}),g);crystal.rotation.z=.25;const inner=mesh(new THREE.OctahedronGeometry(.25,0),new THREE.MeshBasicMaterial({color:'#fff1bc'}),g);const ring=mesh(new THREE.TorusGeometry(1.1,.018,5,44),new THREE.MeshBasicMaterial({color:'#e8b36b',transparent:true,opacity:.7}),g);ring.rotation.x=Math.PI/2;const beam=mesh(new THREE.CylinderGeometry(.08,1.15,8,12,1,true),beaconMat,g);beam.position.y=3.1;const light=new THREE.PointLight('#f0a74f',3,10);g.add(light);return {group:g,crystal,ring,beam,light,x,z,y,picked:false,index:i}}
const shards=[createShard(24,5,1),createShard(-34,-18,2),createShard(25,49,3)];

function makeGuide(){const g=new THREE.Group(),x=-7,z=12,y=terrainHeight(x,z);g.position.set(x,y,z);scene.add(g);const robe=mesh(new THREE.CylinderGeometry(.42,.72,1.8,8),mats.cloth,g);robe.position.y=.9;const belt=mesh(new THREE.TorusGeometry(.44,.07,6,12),mats.clothLight,g);belt.position.y=.72;belt.rotation.x=Math.PI/2;const head=mesh(new THREE.SphereGeometry(.37,10,8),mats.skin,g);head.position.y=2;const hood=mesh(new THREE.SphereGeometry(.44,9,7,0,Math.PI*2,0,Math.PI*.56),mats.clothLight,g);hood.position.y=2.15;const pack=mesh(new THREE.BoxGeometry(.62,.85,.35),mats.bark,g);pack.position.set(0,1.12,-.45);const staff=mesh(new THREE.CylinderGeometry(.045,.07,2.1,7),mats.barkLight,g);staff.position.set(.62,1.05,.05);const tip=mesh(new THREE.OctahedronGeometry(.2),new THREE.MeshStandardMaterial({color:'#86aaa0',emissive:'#39756b',emissiveIntensity:.7}),g);tip.position.set(.62,2.12,.05);return {group:g,x,z,y}}
const guide=makeGuide();
function makeWraith(x,z,i){const g=new THREE.Group();g.position.set(x,terrainHeight(x,z)+1,z);scene.add(g);const core=mesh(new THREE.IcosahedronGeometry(.58,1),new THREE.MeshStandardMaterial({color:'#4c3435',emissive:'#8e372f',emissiveIntensity:1.15,roughness:.45}),g);core.scale.set(.85,1.1,.8);const eyeMat=new THREE.MeshBasicMaterial({color:'#ffce82'});for(const ex of [-.2,.2]){const e=mesh(new THREE.SphereGeometry(.075,8,7),eyeMat,g);e.position.set(ex,.12,.48)}for(let j=0;j<3;j++){const tend=mesh(new THREE.ConeGeometry(.17,.95,6),mat('#514040'),g);tend.position.set((j-1)*.34,-.78,-.05);tend.rotation.z=(j-1)*-.45}const glow=new THREE.PointLight('#d44d34',.65,5);glow.position.y=.25;g.add(glow);return {group:g,core,x,z,homeX:x,homeZ:z,hp:2,alive:true,cooldown:0,phase:i*2.4,glow}}
const enemies=[makeWraith(26,3,0),makeWraith(-30,-18,1),makeWraith(28,47,2),makeWraith(47,25,3)];
const player={x:0,z:20,yaw:0,pitch:0,health:100,shards:0,started:false,locked:false,alive:true,attack:0,hitCooldown:0,move:new THREE.Vector2(),time:0};
camera.rotation.order='YXZ'; scene.add(camera);camera.position.set(0,terrainHeight(0,20)+1.72,20);
// A hand-held, ash-steel blade gives every strike a readable physical arc.
const sword=new THREE.Group();const grip=mesh(new THREE.CylinderGeometry(.055,.075,.48,7),mats.bark,sword);grip.rotation.x=.22;grip.position.set(0,-.28,0);const guard=mesh(new THREE.BoxGeometry(.52,.09,.13),mats.metal,sword);guard.position.set(0,-.02,0);guard.rotation.z=-.2;const blade=mesh(new THREE.BoxGeometry(.16,.95,.07),new THREE.MeshStandardMaterial({color:'#c6c5b6',metalness:.78,roughness:.25}),sword);blade.position.set(0,.47,0);blade.rotation.z=-.12;const pommel=mesh(new THREE.SphereGeometry(.11,7,6),mat('#c39b63'),sword);pommel.position.set(0,-.54,0);camera.add(sword);sword.position.set(.62,-.52,-.85);sword.rotation.set(-.3,-.25,-.3);
const $=s=>document.querySelector(s),hud=$('#hud'),titleScreen=$('#title-screen'),prompt=$('#prompt'),toast=$('#toast');let activeTarget=null,toastTimer=0,flashTimer=0,joy={x:0,y:0},audioCtx=null;
function notify(text){toast.textContent=text;toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),2500)}
function updateQuest(){const n=player.shards;$('#quest-count').textContent=`${n} / 3`;$('#quest-progress').style.width=`${n/3*100}%`;if(n<3){$('#quest-objective').textContent=`Find the three lost embers · ${n} found`;$('#quest-title').textContent='The Embers Remember'}else{$('#quest-objective').textContent='Return to the Ash-Reader';$('#quest-title').textContent='A Light Carried Home'}}
function nearestTarget(){let best=null,dist=4.2;for(const s of shards)if(!s.picked){const d=Math.hypot(player.x-s.x,player.z-s.z);if(d<dist){best={type:'shard',item:s,d};dist=d}}const gd=Math.hypot(player.x-guide.x,player.z-guide.z);if(gd<4&&gd<dist){best={type:'guide',item:guide,d:gd};dist=gd}return best}
function interact(){const t=nearestTarget();if(!t){notify('Only the wind answers.');return}if(t.type==='shard'){t.item.picked=true;scene.remove(t.item.group);player.shards++;updateQuest();notify(`Ember ${t.item.index} reclaimed · ${player.shards}/3`);if(player.shards===3)notify('The Ash-Reader is waiting at the shrine.');return}if(player.shards<3){notify(`ASH-READER · “The island broke these lights apart. ${3-player.shards} still call from the ash.”`)}else{$('#ending').classList.remove('hidden');document.exitPointerLock?.();player.locked=false}}
function attack(){if(player.attack>0||!player.started)return;player.attack=.42;playTone(170,.09,'triangle',.045);let target=null,nearest=5.1;const forward=new THREE.Vector3(-Math.sin(player.yaw),0,-Math.cos(player.yaw));for(const e of enemies){if(!e.alive)continue;const dx=e.group.position.x-player.x,dz=e.group.position.z-player.z,d=Math.hypot(dx,dz);const dot=(dx*forward.x+dz*forward.z)/Math.max(d,.001);if(d<nearest&&dot>.15){nearest=d;target=e}}if(target){target.hp--;target.group.position.x+=forward.x*1.35;target.group.position.z+=forward.z*1.35;target.core.material.emissiveIntensity=2.7;setTimeout(()=>{if(target.alive)target.core.material.emissiveIntensity=1.15},130);if(target.hp<=0){target.alive=false;scene.remove(target.group);notify('The ash-born spirit dissolves.');playTone(380,.2,'sine',.055)}else notify('A clean strike. Keep moving.')}}
function playTone(freq,duration,type='sine',volume=.03){try{audioCtx??=new AudioContext();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(volume,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+duration)}catch{}}
$('#begin').addEventListener('click',()=>{player.started=true;titleScreen.classList.add('gone');hud.classList.remove('hidden');renderer.domElement.requestPointerLock?.();notify('Find the lost embers. The shrine lies behind you.');if(audioCtx?.state==='suspended')audioCtx.resume()});
$('#resume').addEventListener('click',()=>{ $('#pause-screen').classList.add('hidden');renderer.domElement.requestPointerLock?.() });
$('#play-again').addEventListener('click',()=>location.reload());
$('#sound-toggle').addEventListener('click',e=>{const on=e.currentTarget.dataset.on!=='false';e.currentTarget.dataset.on=String(!on);e.currentTarget.querySelector('span').textContent=on?'SOUND OFF':'SOUND ON';if(!on){playTone(440,.12,'sine',.025)}});
document.addEventListener('pointerlockchange',()=>{player.locked=document.pointerLockElement===renderer.domElement;if(!player.locked&&player.started&&!$('#ending').classList.contains('hidden'))return;if(!player.locked&&player.started&&!isTouch){$('#pause-screen').classList.remove('hidden')}});
let isTouch=('ontouchstart'in window)||navigator.maxTouchPoints>0;
document.addEventListener('mousemove',e=>{if(player.locked){player.yaw-=e.movementX*.0022;player.pitch=Math.max(-1.15,Math.min(1.15,player.pitch-e.movementY*.0018))}});
document.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(['w','a','s','d',' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();keys.add(k);if(k==='e'&&!e.repeat)interact();if(k===' '&&!e.repeat)attack();if(k==='escape'&&player.started&&!isTouch)$('#pause-screen').classList.toggle('hidden')});document.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));const keys=new Set();
renderer.domElement.addEventListener('click',()=>{if(player.started&&!player.locked&&!isTouch&&$('#pause-screen').classList.contains('hidden'))renderer.domElement.requestPointerLock?.();else if(player.locked)attack()});
renderer.domElement.addEventListener('contextmenu',e=>e.preventDefault());
// Simple mobile thumbstick + generous action buttons; camera turns by dragging the world.
if(isTouch){const controls=document.createElement('div');controls.id='touch-controls';controls.innerHTML='<div class="stick-zone"><div class="stick-base"><div class="stick-knob"></div></div></div><div class="touch-actions"><button class="touch-interact">E<br><small>USE</small></button><button class="touch-attack">⚔<br><small>STRIKE</small></button></div>';document.body.appendChild(controls);const zone=controls.querySelector('.stick-zone'),base=controls.querySelector('.stick-base'),knob=controls.querySelector('.stick-knob');let stickId=null,origin=null;zone.addEventListener('pointerdown',e=>{e.preventDefault();stickId=e.pointerId;const r=base.getBoundingClientRect();origin={x:r.left+r.width/2,y:r.top+r.height/2};zone.setPointerCapture(e.pointerId);moveStick(e)});zone.addEventListener('pointermove',e=>{if(e.pointerId===stickId)moveStick(e)});const endStick=e=>{if(e.pointerId===stickId){stickId=null;joy.x=joy.y=0;knob.style.transform='translate(0,0)'}};zone.addEventListener('pointerup',endStick);zone.addEventListener('pointercancel',endStick);function moveStick(e){let dx=e.clientX-origin.x,dy=e.clientY-origin.y,l=Math.hypot(dx,dy),max=39;if(l>max){dx=dx/l*max;dy=dy/l*max}joy.x=dx/max;joy.y=dy/max;knob.style.transform=`translate(${dx}px,${dy}px)`}controls.querySelector('.touch-attack').addEventListener('pointerdown',e=>{e.preventDefault();attack()});controls.querySelector('.touch-interact').addEventListener('pointerdown',e=>{e.preventDefault();interact()});let drag=null;renderer.domElement.addEventListener('pointerdown',e=>{if(e.pointerType==='touch'&&e.clientX>innerWidth*.42)drag={x:e.clientX,y:e.clientY,id:e.pointerId}});renderer.domElement.addEventListener('pointermove',e=>{if(drag&&drag.id===e.pointerId){player.yaw-=(e.clientX-drag.x)*.004;player.pitch=Math.max(-1.15,Math.min(1.15,player.pitch-(e.clientY-drag.y)*.003));drag.x=e.clientX;drag.y=e.clientY}});renderer.domElement.addEventListener('pointerup',e=>{if(drag?.id===e.pointerId)drag=null})}

function updateWorld(dt){player.time+=dt;player.attack=Math.max(0,player.attack-dt);player.hitCooldown=Math.max(0,player.hitCooldown-dt);const forward=new THREE.Vector3(-Math.sin(player.yaw),0,-Math.cos(player.yaw));const right=new THREE.Vector3(Math.cos(player.yaw),0,-Math.sin(player.yaw));let mx=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0)+joy.x;let mz=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0)+joy.y;let moving=Math.hypot(mx,mz);if(moving>1){mx/=moving;mz/=moving}const speed=(keys.has('shift')?10.3:6.1);player.x+=(right.x*mx-forward.x*mz)*speed*dt;player.z+=(right.z*mx-forward.z*mz)*speed*dt;player.x=THREE.MathUtils.clamp(player.x,-91,91);player.z=THREE.MathUtils.clamp(player.z,-91,91);
 const floor=terrainHeight(player.x,player.z)+1.72;camera.position.set(player.x,floor+(moving>.1?Math.sin(player.time*(keys.has('shift')?14:10))*.045:0),player.z);camera.rotation.set(player.pitch,player.yaw,0,'YXZ');
 const swing=player.attack>0?Math.sin((.42-player.attack)/.42*Math.PI):0;sword.rotation.x=-.3+swing*.95;sword.rotation.y=-.25-swing*.8;sword.rotation.z=-.3-swing*.62;sword.position.set(.62+swing*.16,-.52+swing*.08,-.85);
 for(const s of shards){if(s.picked)continue;s.group.position.y=s.y+.9+Math.sin(player.time*1.6+s.index)*.14;s.crystal.rotation.y+=dt*.75;s.ring.rotation.z+=dt*.3;s.light.intensity=2.2+Math.sin(player.time*2+s.index)*.45}
 guide.group.position.y=guide.y+Math.sin(player.time*1.4)*.035;guide.group.rotation.y=Math.atan2(player.x-guide.x,player.z-guide.z);
 for(const e of enemies){if(!e.alive)continue;e.cooldown=Math.max(0,e.cooldown-dt);const dx=player.x-e.group.position.x,dz=player.z-e.group.position.z,d=Math.hypot(dx,dz);const active=d<13;let vx=0,vz=0;if(active&&d>1.55){vx=dx/d;vz=dz/d}else if(!active){const hx=e.homeX-e.group.position.x,hz=e.homeZ-e.group.position.z,hd=Math.hypot(hx,hz);if(hd>1.7){vx=hx/hd;vz=hz/hd}else{vx=Math.sin(player.time*.5+e.phase)*.12;vz=Math.cos(player.time*.5+e.phase)*.12}}e.group.position.x+=vx*(active?2.45:.65)*dt;e.group.position.z+=vz*(active?2.45:.65)*dt;e.group.position.y=terrainHeight(e.group.position.x,e.group.position.z)+1.05+Math.sin(player.time*2.7+e.phase)*.28;e.group.rotation.y=Math.atan2(dx,dz);e.core.rotation.y+=dt*.55;e.core.rotation.z=Math.sin(player.time*1.8+e.phase)*.13;if(d<1.8&&e.cooldown<=0){e.cooldown=1.45;if(player.hitCooldown<=0){player.health=Math.max(0,player.health-12);player.hitCooldown=.62;$('#health-fill').style.width=`${player.health}%`;$('#health-value').textContent=player.health;$('#damage-flash').classList.add('hit');clearTimeout(flashTimer);flashTimer=setTimeout(()=>$('#damage-flash').classList.remove('hit'),190);playTone(85,.15,'sawtooth',.04);if(player.health<=0){player.health=100;$('#health-fill').style.width='100%';$('#health-value').textContent='100';player.x=0;player.z=20;notify('The island lets you wake once more.')}}}}
 const target=nearestTarget();activeTarget=target;if(target)prompt.classList.remove('hidden');else prompt.classList.add('hidden');
 const d=Math.hypot(player.x,player.z);$('#location-name').textContent=d<18?'THE ASHEN COAST':player.z>32?'MUSHROOM GROVE':player.x>25?'BASALT HIGHLANDS':'RED MOUNTAIN FOOTHILLS';const track=document.querySelector('.compass-track');track.style.transform=`translateX(${Math.sin(player.yaw)*12}px)`;
